import { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import { Slider } from "@/components/ui/slider";
import { Calculator, Info } from "lucide-react";

/**
 * PaymentEstimator — adjustable monthly-payment calculator for a vehicle.
 * Pre-populates from `vehiclePrice`; user tweaks credit tier, APR, term,
 * down payment, and trade-in to see a real-time estimate.
 *
 * Formula: standard amortizing loan
 *   M = P · r·(1+r)^n / ((1+r)^n - 1)
 * where r = APR/12/100, n = term months, P = amount financed.
 */

type CreditTier = "excellent" | "good" | "fair" | "challenged";

const CREDIT_TIERS: { id: CreditTier; label: string; score: string; apr: number }[] = [
  { id: "excellent", label: "Excellent", score: "740+", apr: 6.5 },
  { id: "good", label: "Good", score: "680–739", apr: 8.5 },
  { id: "fair", label: "Fair", score: "620–679", apr: 12.0 },
  { id: "challenged", label: "Rebuilding", score: "below 620", apr: 17.0 },
];

const TERM_OPTIONS = [36, 48, 60, 72, 84];

function formatMoney(n: number) {
  return `$${Math.round(n).toLocaleString("en-US")}`;
}

function computeMonthly(principal: number, aprPct: number, termMonths: number) {
  if (principal <= 0 || termMonths <= 0) return 0;
  const r = aprPct / 100 / 12;
  if (r === 0) return principal / termMonths;
  const pow = Math.pow(1 + r, termMonths);
  return (principal * r * pow) / (pow - 1);
}

export function PaymentEstimator({ vehiclePrice }: { vehiclePrice: number }) {
  const [tier, setTier] = useState<CreditTier>("good");
  const [apr, setApr] = useState(CREDIT_TIERS.find((t) => t.id === "good")!.apr);
  const [aprCustomized, setAprCustomized] = useState(false);
  const [term, setTerm] = useState(72);
  // Defaults: 10% down, no trade-in
  const [downPayment, setDownPayment] = useState(Math.round(vehiclePrice * 0.1 / 500) * 500);
  const [tradeIn, setTradeIn] = useState(0);

  // Snap APR to the tier preset when the tier changes, UNLESS the user
  // has manually dragged the APR slider.
  useEffect(() => {
    if (aprCustomized) return;
    const preset = CREDIT_TIERS.find((t) => t.id === tier)?.apr ?? 8.5;
    setApr(preset);
  }, [tier, aprCustomized]);

  const financed = Math.max(vehiclePrice - downPayment - tradeIn, 0);
  const monthly = useMemo(() => computeMonthly(financed, apr, term), [financed, apr, term]);
  const totalPaid = monthly * term;
  const totalInterest = Math.max(totalPaid - financed, 0);

  return (
    <section className="mt-10">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div>
          <h2 className="text-xl font-bold tracking-tight">Estimate your payment</h2>
          <p className="text-sm text-muted-foreground mt-1">Adjust the numbers until it fits your budget. No credit check, no commitment.</p>
        </div>
        <span className="inline-flex items-center gap-1.5 bg-pricepro-red/10 text-pricepro-red text-xs font-bold px-3 py-1.5 rounded-full">
          <Calculator className="w-3.5 h-3.5" /> Payment Estimator
        </span>
      </div>

      <div className="mt-4 bg-card border border-border rounded-2xl overflow-hidden">
        <div className="grid grid-cols-1 md:grid-cols-5">
          {/* Controls */}
          <div className="md:col-span-3 p-6 md:p-8 space-y-6">
            {/* Credit tier */}
            <div>
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Your credit</label>
              <div className="mt-2 grid grid-cols-2 gap-2">
                {CREDIT_TIERS.map((t) => {
                  const active = tier === t.id;
                  return (
                    <button
                      key={t.id}
                      type="button"
                      onClick={() => {
                        setTier(t.id);
                        setAprCustomized(false);
                      }}
                      className={`text-left rounded-lg border px-3 py-2.5 transition-all ${
                        active
                          ? "border-pricepro-red bg-pricepro-red/10 ring-1 ring-pricepro-red/40"
                          : "border-border hover:border-pricepro-red/40 hover:bg-muted/30"
                      }`}
                    >
                      <p className={`text-sm font-bold ${active ? "text-pricepro-red" : "text-foreground"}`}>{t.label}</p>
                      <p className="text-[11px] text-muted-foreground mt-0.5">{t.score} · ~{t.apr}% APR</p>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* APR slider */}
            <div>
              <div className="flex items-baseline justify-between">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Interest Rate (APR)</label>
                <span className="text-sm font-bold tabular-nums">{apr.toFixed(2)}%</span>
              </div>
              <Slider
                className="mt-3"
                min={2}
                max={25}
                step={0.1}
                value={[apr]}
                onValueChange={([v]) => {
                  setApr(v);
                  setAprCustomized(true);
                }}
              />
              <div className="mt-1 flex justify-between text-[10px] text-muted-foreground">
                <span>2%</span>
                <span>25%</span>
              </div>
            </div>

            {/* Loan term */}
            <div>
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Loan term</label>
              <div className="mt-2 grid grid-cols-5 gap-2">
                {TERM_OPTIONS.map((m) => {
                  const active = term === m;
                  return (
                    <button
                      key={m}
                      type="button"
                      onClick={() => setTerm(m)}
                      className={`rounded-lg border px-2 py-2.5 text-xs font-bold transition-all ${
                        active
                          ? "border-pricepro-red bg-pricepro-red text-pricepro-red-foreground"
                          : "border-border text-foreground hover:border-pricepro-red/40 hover:bg-muted/30"
                      }`}
                    >
                      {m} mo
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Down payment + trade-in */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
              <div>
                <div className="flex items-baseline justify-between">
                  <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Down payment</label>
                  <span className="text-sm font-bold tabular-nums">{formatMoney(downPayment)}</span>
                </div>
                <Slider
                  className="mt-3"
                  min={0}
                  max={Math.round(vehiclePrice * 0.6)}
                  step={500}
                  value={[downPayment]}
                  onValueChange={([v]) => setDownPayment(v)}
                />
              </div>
              <div>
                <div className="flex items-baseline justify-between">
                  <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Trade-in value</label>
                  <span className="text-sm font-bold tabular-nums">{formatMoney(tradeIn)}</span>
                </div>
                <Slider
                  className="mt-3"
                  min={0}
                  max={40000}
                  step={500}
                  value={[tradeIn]}
                  onValueChange={([v]) => setTradeIn(v)}
                />
              </div>
            </div>
          </div>

          {/* Summary panel */}
          <div className="md:col-span-2 bg-surface p-6 md:p-8 border-t md:border-t-0 md:border-l border-border flex flex-col justify-between">
            <div>
              <p className="text-xs text-muted-foreground uppercase tracking-wider font-semibold">Estimated Monthly Payment</p>
              <div className="mt-2 flex items-baseline gap-1">
                <motion.span
                  key={`${Math.round(monthly)}-${term}-${apr}`}
                  initial={{ opacity: 0.6, y: 3 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.2 }}
                  className="text-4xl md:text-5xl font-bold text-pricepro-red tabular-nums"
                >
                  {formatMoney(monthly)}
                </motion.span>
                <span className="text-lg text-muted-foreground">/mo</span>
              </div>

              <div className="mt-5 space-y-2.5 text-sm">
                <div className="flex items-center justify-between">
                  <span className="text-muted-foreground">Vehicle price</span>
                  <span className="font-medium tabular-nums">{formatMoney(vehiclePrice)}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-muted-foreground">Down + trade-in</span>
                  <span className="font-medium tabular-nums">− {formatMoney(downPayment + tradeIn)}</span>
                </div>
                <div className="flex items-center justify-between pt-2 border-t border-border">
                  <span className="text-muted-foreground">Amount financed</span>
                  <span className="font-semibold tabular-nums">{formatMoney(financed)}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-muted-foreground">Total interest</span>
                  <span className="font-medium tabular-nums">{formatMoney(totalInterest)}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-muted-foreground">Total of payments</span>
                  <span className="font-medium tabular-nums">{formatMoney(totalPaid)}</span>
                </div>
              </div>
            </div>

            <p className="mt-6 flex items-start gap-2 text-[11px] text-muted-foreground leading-relaxed">
              <Info className="w-3.5 h-3.5 mt-0.5 flex-shrink-0" />
              <span>
                Estimate only. Actual APR and terms depend on credit approval, loan-to-value, and lender. Tax, title, and registration not included.
              </span>
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

