        className="w-full h-11 pl-4 pr-9 rounded-full bg-transparent text-foreground text-sm font-medium border-0 outline-none appearance-none cursor-pointer hover:bg-foreground/5 transition-colors truncate"
      >
        {options.map((opt) => (
          <option key={opt} value={opt}>
            {opt}
          </option>
        ))}
