import { Link } from "@tanstack/react-router";
import { useRef } from "react";
import { motion, useMotionValue, useSpring, useTransform, useReducedMotion } from "framer-motion";
import { Button } from "@/components/ui/button";
import { ShieldCheck } from "lucide-react";

interface VehicleCardProps {
  id?: string;
  name: string;
  year: string;
  image: string;
  price: string;
  marketPrice?: string;
  savings?: string;
  leasePrice?: string;
  tag?: string;
  mileage?: string;
  /** Inspection grade — surfaces transparency on the card. */
  condition?: "Excellent" | "Very Good" | "Good";
  /** Count of documented imperfections — shown alongside condition. */
  flawCount?: number;
}

export function VehicleCard({
  id,
  name,
  year,
  image,
  price,
  marketPrice,
  savings,
  leasePrice,
  tag,
  mileage,
  condition,
  flawCount,
}: VehicleCardProps) {
  const reduce = useReducedMotion();
  const cardRef = useRef<HTMLDivElement>(null);

  // Mouse-tracked position normalized to −0.5..0.5 over the card. Spring-smoothed
  // so the sheen doesn't jitter. Only used to drive the light-sheen overlay.
  const mx = useMotionValue(0);
  const my = useMotionValue(0);
  const smoothX = useSpring(mx, { stiffness: 180, damping: 22, mass: 0.35 });
  const smoothY = useSpring(my, { stiffness: 180, damping: 22, mass: 0.35 });
  const sheenBackground = useTransform(
    [smoothX, smoothY],
    (latest) => {
      const [x, y] = latest as [number, number];
      const px = (x + 0.5) * 100;
      const py = (y + 0.5) * 100;
      return `radial-gradient(circle at ${px}% ${py}%, rgba(255,255,255,0.35), transparent 45%)`;
    },
  );

  const handleMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (reduce) return;
    const rect = cardRef.current?.getBoundingClientRect();
    if (!rect) return;
    mx.set((e.clientX - rect.left) / rect.width - 0.5);
    my.set((e.clientY - rect.top) / rect.height - 0.5);
  };
  const handleLeave = () => {
    mx.set(0);
    my.set(0);
  };

  const transparencyLabel = condition
    ? flawCount && flawCount > 0
      ? `${condition} · ${flawCount} ${flawCount === 1 ? "note" : "notes"}`
      : condition
    : null;

  return (
    <div
      ref={cardRef}
      onMouseMove={handleMove}
      onMouseLeave={handleLeave}
      className="group relative bg-card rounded-xl overflow-hidden border border-border transition-all duration-300 flex flex-col hover:shadow-xl hover:shadow-foreground/5 hover:-translate-y-1 hover:border-pricepro-red/30"
    >
      <div className="relative aspect-[16/10] md:aspect-[16/9] bg-muted/30 overflow-hidden">
        {tag && (
          <span className="absolute top-3 left-3 z-10 bg-pricepro-red text-pricepro-red-foreground text-xs font-bold px-3 py-1 rounded-md tracking-wide uppercase">
            {tag}
          </span>
        )}
        {savings && (
          <span className="absolute top-3 right-3 z-10 bg-foreground text-background text-xs font-bold px-3 py-1 rounded-md tracking-wide">
            Save {savings}
          </span>
        )}
        {/* layoutId is preserved so the shared-element transition into the
            VDP hero still morphs this card image smoothly. */}
        <motion.img
          layoutId={id ? `vehicle-img-${id}` : undefined}
          src={image}
          alt={`${year} ${name}`}
          className="w-full h-full object-contain transform-gpu group-hover:scale-[1.04] transition-transform duration-500 ease-out will-change-transform"
          loading="lazy"
          decoding="async"
        />
        {/* Cursor-tracked specular sheen — only visible on hover */}
        <motion.div
          aria-hidden
          className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none mix-blend-overlay"
          style={reduce ? undefined : { background: sheenBackground }}
        />
      </div>
      <div className="p-5 flex flex-col flex-1">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <p className="text-xs text-muted-foreground tracking-wider uppercase font-medium">{year}</p>
            <h3 className="text-base font-bold text-foreground tracking-tight mt-0.5 truncate">{name}</h3>
            {mileage && <p className="text-xs text-muted-foreground mt-1">{mileage} miles</p>}
          </div>
          {transparencyLabel && (
            <span className="inline-flex items-center gap-1 bg-pricepro-red/10 text-pricepro-red text-[10px] font-bold px-2 py-1 rounded-md flex-shrink-0 whitespace-nowrap">
              <ShieldCheck className="w-3 h-3" />
              {transparencyLabel}
            </span>
          )}
        </div>

        <div className="mt-3">
          {marketPrice && (
            <div className="flex items-center gap-2 text-xs">
              <span className="text-muted-foreground">Market</span>
              <span className="text-muted-foreground line-through">{marketPrice}</span>
            </div>
          )}
          <div className="flex items-baseline gap-2 mt-0.5">
            <span className="text-xl font-bold text-pricepro-red">{price}</span>
            {leasePrice && <span className="text-xs text-muted-foreground">or {leasePrice}/mo</span>}
          </div>
          {savings && (
            <p className="text-xs font-semibold text-pricepro-red mt-0.5">Markdown savings of {savings}</p>
          )}
        </div>

        <div className="mt-auto pt-4 flex gap-2">
          {id ? (
            <Link to="/vehicle/$id" params={{ id }} className="flex-1">
              <Button variant="brand" size="default" className="w-full text-sm">
                View Details
              </Button>
            </Link>
          ) : (
            <Button variant="brand" size="default" className="flex-1 text-sm">
              Get This Deal
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

